<?php require 'config.php'; require_login(); $uid=$_SESSION['uid'];
$mon=[]; for ($i=5;$i>=0;$i--) { $f=date('Y-m-01',strtotime("first day of -$i month")); $t=totals($pdo,$uid,$f,date('Y-m-t',strtotime($f))); $mon[date('M Y',strtotime($f))]=$t; }
$mx=max(1,...array_map(fn($t)=>max($t['income'],$t['expense']),$mon)); $y=date('Y'); $ty=totals($pdo,$uid,"$y-01-01","$y-12-31"); $ly=totals($pdo,$uid,($y-1).'-01-01',($y-1).'-12-31');
$a=avg_stats($pdo,$uid); $cs=$pdo->prepare("SELECT category,SUM(amount) s FROM transactions WHERE user_id=? AND type='expense' AND tx_date BETWEEN ? AND ? GROUP BY category ORDER BY s DESC"); $cs->execute([$uid,date('Y-m-01'),date('Y-m-t')]); $cats=$cs->fetchAll(); $ct=array_sum(array_column($cats,'s'));
function pct_change($n,$o){ return $o>0?round(($n-$o)/$o*100):null; }
page_head('Analytics'); ?>
<h1>Analytics</h1>
<h2>Monthly comparison</h2><div class="card"><div class="bars"><?php foreach ($mon as $l=>$t) echo '<div title="'.e($l).'"><i style="height:'.round($t['income']/$mx*100).'px;background:var(--inc)"></i><i style="height:'.round($t['expense']/$mx*100).'px;background:var(--exp)"></i>'.e(substr($l,0,3)).'</div>'; ?></div><p class="note"><span class="pos">Green</span> = income, <span class="neg">red</span> = spending.</p>
<table><tr><th>Month</th><th class="r">Income</th><th class="r">Spending</th><th class="r">Cash flow</th><th class="r">Savings rate</th></tr><?php foreach ($mon as $l=>$t) { $n=$t['income']-$t['expense']; echo '<tr><td>'.e($l).'</td><td class="r">'.money($t['income']).'</td><td class="r">'.money($t['expense']).'</td><td class="r '.($n<0?'neg':'pos').'">'.money($n).'</td><td class="r">'.($t['income']>0?round($n/$t['income']*100).'%':'-').'</td></tr>'; } ?></table></div>
<h2>Year comparison</h2><div class="card scroll"><table><tr><th></th><th class="r"><?= $y-1 ?></th><th class="r"><?= $y ?></th><th class="r">Change</th></tr>
<?php foreach (['income'=>'Income','expense'=>'Spending','balance'=>'Net saved'] as $k=>$l) { $c=pct_change($ty[$k],$ly[$k]); echo '<tr><td>'.$l.'</td><td class="r">'.money($ly[$k]).'</td><td class="r">'.money($ty[$k]).'</td><td class="r">'.($c===null?'-':($c>0?'+':'').$c.'%').'</td></tr>'; } ?></table></div>
<h2>Category analysis (this month)</h2><div class="card scroll"><table><tr><th>Category</th><th class="r">Spent</th><th>Share</th></tr><?php foreach ($cats as $c) { $p=$ct>0?round($c['s']/$ct*100):0; echo '<tr><td>'.e($c['category']).'</td><td class="r">'.money($c['s']).'</td><td>'.bar($p).'<span class="note">'.$p.'%</span></td></tr>'; } if (!$cats) echo '<tr><td colspan="3">No spending this month yet.</td></tr>'; ?></table></div>
<h2>Savings rate</h2><div class="card"><p>Over the last <?= $a['months'] ?> month(s) you saved <b><?= $a['inc']>0?round($a['net']/$a['inc']*100):0 ?>%</b> of your income on average. A common target is 20%.</p></div>
<h2>Spending patterns</h2><?php if (!is_premium()) echo '<div class="card">Pattern detection is part of Advanced analytics (Premium). <a href="plans.php">See plans</a></div>'; else {
  $d=$pdo->prepare("SELECT DAYOFWEEK(tx_date) d,SUM(amount) s,COUNT(DISTINCT tx_date) n FROM transactions WHERE user_id=? AND type='expense' AND tx_date>=? GROUP BY d"); $d->execute([$uid,date('Y-m-d',strtotime('-90 days'))]); $dw=[]; foreach ($d as $r) $dw[(int)$r['d']]=$r['s']/max(1,$r['n']); $names=[1=>'Sunday',2=>'Monday',3=>'Tuesday',4=>'Wednesday',5=>'Thursday',6=>'Friday',7=>'Saturday'];
  $f=$pdo->prepare("SELECT description,COUNT(*) n,SUM(amount) s FROM transactions WHERE user_id=? AND type='expense' AND description<>'' AND tx_date>=? GROUP BY description HAVING n>=3 ORDER BY n DESC LIMIT 5"); $f->execute([$uid,date('Y-m-d',strtotime('-90 days'))]); ?>
<div class="card"><?php if ($dw) { arsort($dw); $top=array_key_first($dw); echo '<p>You spend the most on <b>'.$names[$top].'s</b> (about '.money($dw[$top]).' on an average one over the last 90 days).</p>'; } else echo '<p>Not enough data yet.</p>';
  $fr=$f->fetchAll(); if ($fr) { echo '<p>Things you pay for again and again:</p><ul>'; foreach ($fr as $r) echo '<li>'.e($r['description']).': '.$r['n'].' times, '.money($r['s']).' in total</li>'; echo '</ul>'; } ?></div><?php } page_foot();
